// حساب السعر العادل
app.get('/api/pricing/calculate', (req, res) => {
    const { cost, category, metal } = req.query;

    if (!cost || !category) {
        return res.status(400).json({
            success: false,
            error: 'يجب تحديد التكلفة (cost) والفئة (category)',
            example: '/api/pricing/calculate?cost=2000&category=baseMetals&metal=iron'
        });
    }

    const baseCost = parseFloat(cost);
    const fairPrice = calculateFairPrice(baseCost, category, metal);
    const FPM = SHEIKHA_PRICING_CONSTANTS.FPM[category] || 0.1;

    res.json({
        success: true,
        calculation: {
            baseCost: baseCost,
            category: category,
            metal: metal || 'general',
            profitMargin: FPM,
            fairPrice: fairPrice,
            minPrice: Math.round(baseCost * SHEIKHA_PRICING_CONSTANTS.PPF * 100) / 100,
            maxPrice: Math.round(baseCost * (1 + FPM) * SHEIKHA_PRICING_CONSTANTS.CPF * 100) / 100,
            currency: 'SAR'
        },
        formula: 'السعر العادل = التكلفة × (1 + هامش الربح) × متغيرات السوق',
        principle: 'لا ضرر ولا ضرار'
    });
});

// أسعار شيخة العادلة
app.get('/api/prices/sheikha', (req, res) => {
    const currency = (req.query.currency || 'SAR').toUpperCase();
    const rate = CURRENCY_RATES[currency] ? CURRENCY_RATES[currency].rate : 1;

    // تحويل الأسعار للعملة المطلوبة
    const convertPrice = price => Math.round((price / rate) * 100) / 100;

    const convertedPrices = {
        baseMetals: {},
        preciousMetals: {},
        scrap: {}
    };

    Object.keys(SHEIKHA_FAIR_PRICES.baseMetals).forEach(key => {
        const item = SHEIKHA_FAIR_PRICES.baseMetals[key];
        convertedPrices.baseMetals[key] = {
            ...item,
            fairPrice: convertPrice(item.fairPrice),
            cost: convertPrice(item.cost),
            currency: currency
        };
    });

    Object.keys(SHEIKHA_FAIR_PRICES.preciousMetals).forEach(key => {
        const item = SHEIKHA_FAIR_PRICES.preciousMetals[key];
        convertedPrices.preciousMetals[key] = {
            ...item,
            fairPrice: convertPrice(item.fairPrice),
            cost: convertPrice(item.cost),
            currency: currency
        };
    });

    Object.keys(SHEIKHA_FAIR_PRICES.scrap).forEach(key => {
        const item = SHEIKHA_FAIR_PRICES.scrap[key];
        convertedPrices.scrap[key] = {
            ...item,
            minPrice: convertPrice(item.minPrice),
            maxPrice: convertPrice(item.maxPrice),
            currency: currency
        };
    });

    res.json({
        success: true,
        prices: convertedPrices,
        currency: currency,
        currencyInfo: CURRENCY_RATES[currency] || CURRENCY_RATES.SAR,
        exchangeRate: rate,
        principle: 'لا ضرر ولا ضرار — تسعير عادل وشفاف',
        timestamp: new Date().toISOString(),
        website: 'www.sheikha.top'
    });
});

