app.post('/api/ai/pricing', express.json(), authOptional, async (req, res) => {
    const { metalType, quantity, quality, region } = req.body || {};
    if (!metalType)
        return res
            .status(400)
            .json({ success: false, message: 'يرجى تحديد نوع المعدن (metalType)' });

    try {
        const result = await callPricingLLM(
            metalType || 'غير محدد',
            quantity || 'غير محدد',
            quality || 'متوسط',
            region || 'السعودية'
        );

        if (result.error) {
            // إذا لم يكن AI مفعلاً، نقدم تقدير بسيط
            const basePrices = { حديد: 2400, نحاس: 32000, ألمنيوم: 8200, ستانلس: 6500 };
            const basePrice = basePrices[metalType] || 2000;
            return res.json({
                success: true,
                pricing: {
                    suggested: basePrice,
                    range: { min: basePrice * 0.9, max: basePrice * 1.1 },
                    source: 'تقدير النظام',
                    note: 'للحصول على تحليل ذكي أدق، فعّل OPENAI_API_KEY'
                }
            });
        }

        res.json({
            success: true,
            pricing: {
                analysis: result.reply,
                source: 'تحليل ذكي',
                model: result.model
            },
            usage: result.usage
        });
    } catch (e) {
        res.status(500).json({ success: false, message: 'خطأ داخلي', detail: e.message });
    }
});

