// توثيق الهوية الوطنية عبر نفاذ (محاكاة — يُربط بـ API نفاذ الحقيقي لاحقاً)
app.post('/api/admin/verify-nafath', authRequired, (req, res) => {
    if (req.user.role !== 'admin')
        return res.status(403).json({ success: false, message: 'صلاحيات المدير مطلوبة.' });
    const { nationalId, nafathCode } = req.body || {};
    if (!nationalId) return res.status(400).json({ success: false, message: 'رقم الهوية مطلوب.' });

    const user = USERS.find(u => u.id === req.user.id);
    if (!user) return res.status(404).json({ success: false });

    if (!user.identity) user.identity = {};
    user.identity.nationalId = nationalId;
    user.identity.nafathStatus = 'verified';
    user.identity.idVerifiedAt = new Date().toISOString();
    user.nafathVerified = true;
    if (!user.securityLog) user.securityLog = [];
    user.securityLog.push({
        action: 'nafath_identity_verified',
        at: new Date().toISOString(),
        nationalIdLast4: nationalId.slice(-4),
        quran: 'إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا — النساء ٥٨'
    });
    user.updatedAt = new Date().toISOString();
    saveJSON(USERS_FILE, USERS);
    res.json({
        success: true,
        message: 'تم توثيق الهوية عبر نفاذ بنجاح.',
        identity: user.identity
    });
});

