app.put('/api/products/:id', authRequired, (req, res) => {
    const listing = LISTINGS.find(l => l.id === req.params.id);
    if (!listing) return res.status(404).json({ success: false, message: 'المنتج غير موجود.' });
    if (listing.traderId !== req.user.id)
        return res.status(403).json({ success: false, message: 'غير مصرح بتعديل هذا المنتج.' });
    const {
        name,
        hsCode,
        description,
        quantity,
        unit,
        weight,
        price,
        currency,
        locationAddress,
        locationLat,
        locationLng,
        proofOfOwnership,
        supplyChainStage,
        scrapType
    } = req.body || {};
    if (name !== undefined) listing.name = name.trim();
    if (hsCode !== undefined) {
        const hs = getHSCategory(hsCode);
        listing.hsCode = hs.id;
        listing.category = hs.id;
        listing.categoryName = hs.nameAr;
    }
    if (description !== undefined) listing.description = description.trim();
    if (quantity !== undefined) listing.quantity = quantity;
    if (unit !== undefined) listing.unit = unit;
    if (weight !== undefined) listing.weight = weight;
    if (price !== undefined) listing.price = price;
    if (currency !== undefined) listing.currency = currency;
    if (locationAddress !== undefined) listing.locationAddress = locationAddress.trim();
    if (locationLat !== undefined) listing.locationLat = locationLat;
    if (locationLng !== undefined) listing.locationLng = locationLng;
    if (proofOfOwnership !== undefined) listing.proofOfOwnership = proofOfOwnership.trim();
    if (supplyChainStage !== undefined) listing.supplyChainStage = getStage(supplyChainStage).id;
    if (scrapType !== undefined) listing.scrapType = getScrapDisplayType(scrapType).id;
    saveJSON(LISTINGS_FILE, LISTINGS);
    logOperation(
        'listing_edit',
        'listing',
        { id: listing.id, name: listing.name, price: listing.price, quantity: listing.quantity },
        listing
    );
    const hs = getHSCategory(listing.hsCode || listing.category);
    res.json({
        success: true,
        product: { ...listing, icon: hs.icon },
        message: 'تم تحديث المنتج.'
    });
});

