// API: أسعار منطقة محددة
app.get('/api/prices/regional/:region', (req, res) => {
    const region = req.params.region;
    const regionData = SHEIKHA_PRICING_SYSTEM.regionFactors[region];

    if (!regionData) {
        return res
            .status(404)
            .json({
                success: false,
                error: 'منطقة غير معروفة',
                availableRegions: Object.keys(SHEIKHA_PRICING_SYSTEM.regionFactors)
            });
    }

    // حساب أسعار كل المعادن لهذه المنطقة
    const prices = {};
    for (const [key, metal] of Object.entries(SHEIKHA_REFERENCE_PRICES.basemetals)) {
        prices[key] = {
            ...metal,
            regionalPrice: Math.round(metal.sheikha * regionData.factor)
        };
    }

    res.json({
        success: true,
        region,
        regionData,
        prices,
        timestamp: new Date().toISOString()
    });
});

// API: تاريخ الأسعار (تم حذف المسار المكرر /api/index/smi — المسار الأصلي في السطر 2080)
app.get('/api/history/:metal/:period', (req, res) => {
    const { metal, period } = req.params;

    // توليد بيانات تاريخية تجريبية
    const days = period === 'week' ? 7 : period === 'month' ? 30 : period === 'year' ? 365 : 7;
    const metalData =
        SHEIKHA_REFERENCE_PRICES.basemetals[metal] ||
        SHEIKHA_REFERENCE_PRICES.precious[metal] ||
        SHEIKHA_REFERENCE_PRICES.scrap[metal];

    if (!metalData) {
        return res.status(404).json({ success: false, error: 'معدن غير معروف' });
    }

    const history = [];
    const basePrice = metalData.sheikha;
    for (let i = days; i >= 0; i--) {
        const date = new Date();
        date.setDate(date.getDate() - i);
        const variation = (Math.random() - 0.5) * 0.1; // ±5% تقلب
        history.push({
            date: date.toISOString().split('T')[0],
            price: Math.round(basePrice * (1 + variation)),
            volume: Math.round(Math.random() * 10000)
        });
    }

    res.json({
        success: true,
        metal: metalData.nameAr,
        period,
        history,
        average: Math.round(history.reduce((s, h) => s + h.price, 0) / history.length),
        min: Math.min(...history.map(h => h.price)),
        max: Math.max(...history.map(h => h.price)),
        timestamp: new Date().toISOString()
    });
});

// API: حاسبة السعر العادل
app.get('/api/prices/calculate', (req, res) => {
    const { metal, region, quality, quantity } = req.query;

    if (!metal) {
        return res.status(400).json({ success: false, error: 'يجب تحديد المعدن' });
    }

    const result = calculateSheikhaFairPrice(
        metal,
        region || 'السعودية',
        quality || 'B',
        parseFloat(quantity) || 1
    );

    if (result.error) {
        return res.status(404).json({ success: false, error: result.error });
    }

    res.json({
        success: true,
        calculation: result,
        formula: 'سعر شيخة = السعر المرجعي × معامل المنطقة × معامل الجودة',
        principles: 'لا ضرر ولا ضرار — العدل في الميزان',
        timestamp: new Date().toISOString()
    });
});

app.get('/api/ai/pricing-suggestion', (req, res) => {
    const category = (req.query.category || '').toString().toLowerCase();
    const quantity = parseFloat(req.query.quantity) || 1;
    const unit = (req.query.unit || 'طن').toString();
    const region = req.query.region || 'السعودية';
    const quality = req.query.quality || 'B';

    // البحث في أسعار شيخة أولاً
    const keyMap = {
        steelrebar: 'iron_rebar',
        حديد: 'iron_rebar',
        iron: 'iron_rebar',
        copper: 'copper_1',
        نحاس: 'copper_1',
        aluminum: 'aluminum_pure',
        ألومنيوم: 'aluminum_pure',
        ألمنيوم: 'aluminum_pure',
        gold: 'gold_24k',
        ذهب: 'gold_24k',
        silver: 'silver_999',
        فضة: 'silver_999',
        hms1: 'iron_hms1',
        hms2: 'iron_hms2',
        stainless: 'stainless_304',
        ستانلس: 'stainless_304'
    };

    const metalKey = keyMap[category] || category;
    const result = calculateSheikhaFairPrice(metalKey, region, quality, quantity);

    if (result.error) {
        // fallback للنظام القديم
        const saudi = LIVE_PRICES.saudi || {};
        const metals = LIVE_PRICES.metals || {};
        let basePrice = saudi[category]?.price || metals[category]?.price || 2000;
        const suggested = Math.round(basePrice * quantity * 1.05);

        return res.json({
            success: true,
            suggestion: {
                category: category || 'عام',
                quantity,
                unit,
                basePricePerUnit: basePrice,
                suggestedTotal: suggested,
                currency: 'SAR',
                note: 'اقتراح مبني على أسعار السوق الحالية'
            },
            timestamp: new Date().toISOString()
        });
    }

    res.json({
        success: true,
        suggestion: {
            category: result.metal,
            categoryEn: result.metalEn,
            quantity,
            unit: result.unit,
            region,
            quality,
            basePricePerUnit: result.fairPricePerUnit,
            suggestedTotal: result.totalPrice,
            currency: 'SAR',
            hsCode: result.hsCode,
            sources: result.sources,
            fairMargin: '5%',
            note: 'سعر شيخة العادل — بلا ضرر ولا ضرار'
        },
        principle: 'وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُوا الْمِيزَانَ',
        timestamp: new Date().toISOString()
    });
});

