app.get('/api/security/status', (req, res) => {
    const uptimeSeconds = Math.floor((Date.now() - SYSTEM_STATUS.uptime) / 1000);
    const uptimeHours = Math.floor(uptimeSeconds / 3600);
    const uptimeMinutes = Math.floor((uptimeSeconds % 3600) / 60);

    res.json({
        success: true,
        status: SYSTEM_STATUS.status,
        uptime: `${uptimeHours}h ${uptimeMinutes}m`,
        uptimeSeconds,
        availability: SECURITY_CONFIG.availability,
        fridayPause: checkFridayPause(),
        lastBackup: SYSTEM_STATUS.lastBackup,
        encryption: SECURITY_CONFIG.encryption.algorithm,
        compliance: SECURITY_CONFIG.compliance,
        backupLocations: SECURITY_CONFIG.backup.locations,
        timestamp: new Date().toISOString()
    });
});

