app.post('/api/customer-journey/step/:stepId', (req, res) => {
    const stepId = parseInt(req.params.stepId);
    const startTime = Date.now();

    // محاكاة تنفيذ الخطوة
    const stepResults = {
        1: {
            // Discovery
            loadTime: (Math.random() * 0.8 + 0.8).toFixed(2),
            ttfb: Math.floor(Math.random() * 100 + 50),
            cls: (Math.random() * 0.05).toFixed(3),
            fcp: Math.floor(Math.random() * 500 + 500),
            lcp: Math.floor(Math.random() * 1000 + 1000)
        },
        2: {
            // Registration
            fieldsCount: 5,
            completionTime: Math.floor(Math.random() * 30 + 45),
            validationErrors: 0,
            otpSent: true,
            otpVerified: true
        },
        3: {
            // Browsing
            productsLoaded: Math.floor(Math.random() * 500 + 1500),
            searchTime: Math.floor(Math.random() * 200 + 100),
            filtersAvailable: 12,
            filtersUsed: Math.floor(Math.random() * 5 + 2),
            pagesViewed: Math.floor(Math.random() * 5 + 3)
        },
        4: {
            // Purchase
            itemsInCart: Math.floor(Math.random() * 3 + 1),
            cartTotal: Math.floor(Math.random() * 5000 + 2000),
            paymentTime: (Math.random() * 2 + 1).toFixed(1),
            paymentMethod: 'mada',
            paymentSuccess: true,
            orderId: 'ORD-' + Date.now()
        },
        5: {
            // Tracking
            trackingNumber: 'SHK' + Math.floor(Math.random() * 900000 + 100000),
            estimatedDelivery: '2-3 أيام',
            statusUpdates: Math.floor(Math.random() * 5 + 3),
            currentStatus: 'في الطريق',
            mapEnabled: true
        },
        6: {
            // Rating
            overallRating: Math.floor(Math.random() * 2 + 4),
            npsScore: Math.floor(Math.random() * 20 + 60),
            feedbackProvided: true,
            wouldRecommend: true
        }
    };

    const result = stepResults[stepId] || {};
    result.stepId = stepId;
    result.executionTime = Date.now() - startTime;
    result.timestamp = new Date().toISOString();

    CUSTOMER_JOURNEY_STATE.steps.push(result);
    CUSTOMER_JOURNEY_STATE.currentStep = stepId;

    res.json({
        success: true,
        step: stepId,
        result,
        progress: Math.round((stepId / 6) * 100)
    });
});

// API إنهاء رحلة العميل
app.post('/api/customer-journey/complete', (req, res) => {
    const totalTime = Date.now() - CUSTOMER_JOURNEY_STATE.startTime;

    // حساب المقاييس النهائية
    const finalMetrics = {
        totalTime: Math.floor(totalTime / 1000),
        stepsCompleted: CUSTOMER_JOURNEY_STATE.steps.length,
        nps: CUSTOMER_JOURNEY_STATE.steps.find(s => s.stepId === 6)?.npsScore || 0,
        csat: Math.floor(Math.random() * 10 + 85),
        ces: (Math.random() * 0.5 + 1.5).toFixed(1),
        conversionRate: 100, // All steps completed
        avgPageLoad: (
            CUSTOMER_JOURNEY_STATE.steps.reduce(
                (acc, s) => acc + (parseFloat(s.loadTime) || 0),
                0
            ) / CUSTOMER_JOURNEY_STATE.steps.length
        ).toFixed(2),
        issues: []
    };

    // تحديد نقاط التحسين
    if (finalMetrics.avgPageLoad > 2) {
        finalMetrics.issues.push({ area: 'الأداء', issue: 'وقت تحميل الصفحات أعلى من الهدف' });
    }

    CUSTOMER_JOURNEY_STATE.active = false;

    res.json({
        success: true,
        message: 'اكتملت رحلة العميل بنجاح',
        journeyId: 'CJ-' + CUSTOMER_JOURNEY_STATE.startTime,
        steps: CUSTOMER_JOURNEY_STATE.steps,
        metrics: finalMetrics,
        timestamp: new Date().toISOString()
    });
});

