app.get('/api/automation/functions', (req, res) => {
    if (!automationEngine) return res.json({ success: false });
    const fns = [...automationEngine.functions.values()];
    const dept = req.query.dept;
    const result = dept ? fns.filter(f => f.dept === dept) : fns;
    res.json({ success: true, total: result.length, functions: result });
});

